const fmt=n=>new Intl.NumberFormat("hu-HU").format(n)+" Ft";let active="all";
const grid=document.querySelector("#productGrid");const sort=document.querySelector("#sort");
function render(){let data=products.filter(p=>active==="all"||p.cats.includes(active));const mode=sort.value;if(mode==="price-asc")data.sort((a,b)=>a.price-b.price);if(mode==="price-desc")data.sort((a,b)=>b.price-a.price);if(mode==="year-desc")data.sort((a,b)=>b.year-a.year);grid.innerHTML=data.map(p=>`<article class="product-card"><div class="card-image"><img src="images/${p.cover}" alt="${p.name} LEGO készlet" loading="lazy"><span class="badge">ELADÓ • ${p.images.length} FOTÓ</span></div><div class="card-body"><div class="card-meta"><span>${p.brand}</span><span>${p.id} • ${p.year}</span></div><h3>${p.name}</h3><p class="card-copy">${p.copy}</p><div class="card-bottom"><span class="price">${fmt(p.price)}</span><button class="details" data-id="${p.id}">Részletek →</button></div></div></article>`).join("");}
document.querySelectorAll(".filter").forEach(b=>b.addEventListener("click",()=>{document.querySelector(".filter.active").classList.remove("active");b.classList.add("active");active=b.dataset.filter;render()}));sort.addEventListener("change",render);render();
const productDialog=document.querySelector("#productDialog"),detail=document.querySelector("#productDetail");
function openProduct(id){const p=products.find(x=>x.id===id);if(!p)return;detail.innerHTML=`<div class="product-detail"><div class="detail-gallery"><div class="detail-main"><img id="detailImage" src="images/${p.images[0]}" alt="${p.name}"></div><div class="thumbs">${p.images.map((im,i)=>`<button class="${i===0?'active':''}" data-image="${im}"><img src="images/${im}" alt="${p.name}, ${i+1}. fotó"></button>`).join("")}</div></div><div class="detail-copy"><p class="eyebrow">LEGO SPEED CHAMPIONS • ${p.id}</p><h2>${p.name}</h2><div class="detail-price">${fmt(p.price)}</div><p class="quote">${p.copy}</p><div class="specs"><div><span>Megjelenés</span><b>${p.year}</b></div><div><span>Autók</span><b>${p.cars}</b></div><div><span>Minifigurák</span><b>${p.figs}</b></div><div><span>Elemek</span><b>${p.pieces||"ellenőrzés alatt"}</b></div></div><p class="notice">Használt, összeépített készlet. A fotókon látható dobozzal, útmutatóval, figurával és plusz elemekkel. A 100%-os alkatrész-teljesség tételes ellenőrzése folyamatban van.</p><button class="button detail-contact" data-subject="LEGO ${p.id} – ${p.name}">Érdekel ez az autó <span>↗</span></button></div></div>`;productDialog.showModal();history.replaceState(null,"",`#lego-${p.id}`);detail.querySelectorAll(".thumbs button").forEach(b=>b.addEventListener("click",()=>{detail.querySelector("#detailImage").src=`images/${b.dataset.image}`;detail.querySelector(".thumbs .active").classList.remove("active");b.classList.add("active")}));detail.querySelector(".detail-contact").addEventListener("click",()=>{productDialog.close();openContact(detail.querySelector(".detail-contact").dataset.subject)})}
grid.addEventListener("click",e=>{const b=e.target.closest("[data-id]");if(b)openProduct(b.dataset.id)});
document.querySelectorAll("dialog").forEach(d=>{d.querySelector(".dialog-close").addEventListener("click",()=>d.close());d.addEventListener("click",e=>{if(e.target===d)d.close()})});productDialog.addEventListener("close",()=>history.replaceState(null,"",location.pathname));
const contactDialog=document.querySelector("#contactDialog"),form=document.querySelector("#contactForm"),subject=document.querySelector("#contactSubject"),result=document.querySelector("#messageResult");
function openContact(s){subject.value=s;form.hidden=false;result.hidden=true;contactDialog.showModal()};document.querySelectorAll(".js-contact").forEach(b=>b.addEventListener("click",()=>openContact(b.dataset.subject)));
form.addEventListener("submit",e=>{e.preventDefault();const d=new FormData(form);document.querySelector("#messageText").textContent=`Név: ${d.get("name")}\nE-mail: ${d.get("email")}\nTárgy: ${d.get("subject")}\n\n${d.get("message")}`;form.hidden=true;result.hidden=false});document.querySelector("#copyMessage").addEventListener("click",async e=>{await navigator.clipboard.writeText(document.querySelector("#messageText").textContent);e.target.textContent="Kimásolva ✓"});
if(location.hash.startsWith("#lego-"))openProduct(location.hash.replace("#lego-",""));
